const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=(n,d=2)=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n)||0);
const fmt=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Not recorded';
const moLabel=m=>new Date(m+'-02T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
const handle=m=>m?.handle||'Unnamed member';const initial=m=>handle(m).replace('@','').slice(0,2).toUpperCase();
const badge=t=>`<span class="tier ${t==='Premium+'?'plus':t==='Premium'?'premium':''}">${esc(t)}</span>`;
const pill=(s,c='')=>`<span class="pill ${c||(['Published','Reposted','Paid','Ready'].includes(s)?'good':['Waiting for content','New','Draft'].includes(s)?'warn':'purple')}">${esc(s)}</span>`;
const btn=(label,action,cls='quiet',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(title,body,action='')=>`<div class="empty"><strong>${title}</strong>${body}${action?'<div>'+action+'</div>':''}</div>`;
const section=(title,sub='',action='')=>`<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const metric=(label,value)=>`<div class="metric"><span>${label}</span><strong>${value}</strong></div>`;
const link=(url,label)=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'<span class="muted">—</span>';
const download=(name,text,type='text/csv')=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
let calendarMode='today',calendarDay=day();
