async function saveSyncResult(action,status,before,checked,issues){const cfg=settings(),run={action,status,at:new Date().toISOString(),checked,added:store.members.filter(m=>!before.has(String(m.id))&&active(m)).length,cancelled:store.members.filter(m=>before.get(String(m.id))===true&&!active(m)).length,issues:[...new Set(issues)]};await store.save('settings',{...cfg,sync_runs:[run,...(cfg.sync_runs||[])].slice(0,10)},cfg.id);}
async function sync(action){if(busy)return;if(preview){toast('Preview does not connect to PayPal.');return}busy=true;const before=new Map(store.members.map(m=>[String(m.id),active(m)])),errors=[],seen=new Set();let checked=0,added=0,updated=0,inactive=0,page=1,phase=action==='sync-countries'?'existing':'discover';const show=text=>{const el=$('sync-progress');if(el){el.hidden=false;el.textContent=text}};try{while(page){const {data:{session:latest}}=await window.sb.auth.getSession();if(!latest)throw Error('Your session expired. Sign in again.');show(`Syncing PayPal · ${phase==='existing'?'checking existing members':'finding subscriptions'} · page ${page} · ${added} added · ${updated} updated · ${inactive} inactive`);const res=await fetch(`/api/paypal?action=${action}&page=${page}&phase=${phase}`,{headers:{Authorization:'Bearer '+latest.access_token},signal:AbortSignal.timeout(65000)});let data;try{data=await res.json()}catch{throw Error('The PayPal endpoint did not return JSON. Check the deployment.')}if(!res.ok||!data.success)throw Error(data.error||'PayPal sync failed.');checked+=data.processed||0;added+=data.added||0;updated+=data.updated||0;inactive+=data.inactive||0;errors.push(...(data.errors||[]).map(x=>x.error),...(data.unknownPlans||[]).map(x=>'Unmapped plan '+x));if(data.pageFingerprint){if(seen.has(data.pageFingerprint))throw Error('PayPal repeated a page. Sync stopped safely; check the API logs.');seen.add(data.pageFingerprint)}page=data.nextPage;if(!page&&phase==='discover'){phase='existing';page=1;seen.clear()}if(page&&(!Number.isInteger(page)||page>10000))throw Error('Unexpected PayPal pagination. Sync stopped safely.');}await refresh(false);await saveSyncResult(action,errors.length?'partial':'complete',before,checked,errors);renderPage();show(`Sync complete · ${added} added · ${updated} updated · ${inactive} marked inactive.${errors.length?' '+errors.length+' issues: '+[...new Set(errors)].join(' · '):''}`);}catch(e){await refresh(false).catch(()=>{});await saveSyncResult(action,'failed',before,checked,[...errors,e.message]).catch(()=>{});renderPage();show('Sync stopped: '+e.message+' Changes from completed pages have been retained.');}finally{busy=false;}}
async function importLocal(){if(preview)throw Error('Local import is disabled in design preview.');const raw=localStorage.getItem('justabarth-club-workspace-v2');if(!raw){toast('No old browser workspace found on this device and domain.');return}if(list('migration').some(m=>m.source==='browser-v2')){toast('This browser workspace has already been imported.');return}const old=JSON.parse(raw);if(!confirm('Import your old notes, check-ins and saved plans into the private shared workspace?'))return;for(const [id,note] of Object.entries(old.notes||{})){if(!member(id)||!note)continue;const p=profile(id);if(!p.notes)await store.save('profile',{...p,member_id:String(id),notes:String(note)},p.id)}for(const [key,done] of Object.entries(old.care||{})){if(!done)continue;const [mth,type,id]=key.split(':');if(!list('care').some(c=>c.import_key===key))await store.save('care',{month:mth,member_id:String(id),type,import_key:key})}for(const [key,rows] of Object.entries(old.plans||{})){for(let i=0;i<rows.length;i++){const r=rows[i],importKey=key+':'+i;if(content().some(p=>p.import_key===importKey))continue;const ids=(r.ids||[]).map(String),m=member(ids[0]);const type=key.endsWith(':groups')?'Basic Club Carousel':tier(m||{})==='Premium+'?(String(r.label).includes('2')?'Premium+ Feature 2':'Premium+ Feature 1'):'Premium Solo';await store.save('content',{title:r.label||'Imported feature',date:r.date,type,member_ids:ids,status:r.done?'Published':'Draft',content_ready:!!r.done,caption_ready:!!r.done,import_key:importKey,notes:'Imported from the previous browser workspace.'})}}await store.save('migration',{source:'browser-v2',imported_at:new Date().toISOString()});$('dialog').close();renderPage();toast('Old workspace imported. Browser backup remains unchanged.');}
async function refresh(snapshot=true){if(preview){renderPage();return}try{await store.load();if(snapshot)await store.snapshot();await ensureRounds();loaded=true;renderPage();}catch(error){toast('Could not refresh: '+error.message,true);throw error}}
function login(message=''){loaded=false;$('app').innerHTML=`<div class="login"><main class="login-box"><div class="eyebrow">JustAbarth / Private operations</div><h1 class="login-brand">THE CONTROL<br>ROOM.</h1><p>The work behind the passion.</p><form id="login-form" class="login-form"><div class="field"><label for="login-email">EMAIL</label><input id="login-email" name="email" class="input" type="email" autocomplete="username" required></div><div class="field"><label for="login-password">PASSWORD</label><input id="login-password" name="password" class="input" type="password" autocomplete="current-password" required></div><div id="form-error" class="note error" role="alert" ${message?'':'hidden'}>${esc(message)}</div><button class="btn primary" type="submit">Enter JA OS →</button><button class="link" type="button" data-action="forgot-password" style="margin-top:20px">Forgot your password?</button></form><div class="login-foot">AUTHORISED CLUB OPERATORS ONLY</div></main></div>`;}
async function boot(){try{if(!window.sb)throw Error('The sign-in library could not load. Check your connection and reload.');const {data:{session:s},error}=await window.sb.auth.getSession();if(error)throw error;if(!s){login();return}session=s;const {data:allowed,error:permissionError}=await window.sb.rpc('ops_is_admin');if(permissionError)throw Error('Private workspace setup is incomplete. Run operating-system.sql and enable-admin.sql in Supabase.');if(!allowed){login('This account is not an authorised JA OS operator.');return}await store.load();await importOctoberSchedule(store);await store.snapshot();await ensureRounds();loaded=true;shell();}catch(e){login(e.message)}}
window.sb?.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY'){$('app').innerHTML=`<div class="login"><main class="login-box"><div class="eyebrow">JustAbarth / Private access</div><h1 class="login-brand">RESET ACCESS.</h1><form id="reset-form" class="login-form">${field('New password','password','','password','required minlength="12" autocomplete="new-password"')}<div id="form-error" class="note error" role="alert" hidden></div><button class="btn primary" type="submit">Save new password</button></form></main></div>`;}if(event==='SIGNED_OUT'&&!preview){$('dialog').close();login();}});
if(['localhost','127.0.0.1'].includes(location.hostname)&&new URLSearchParams(location.search).get('preview')==='1'){
 preview=true;const {makePreview}=await import('./preview.mjs?v=20261006o');store=makePreview();store.records=store.records.filter(r=>r.kind!=='content');for(const row of octoberSchedule([])){const {id,handles,...data}=row;store.records.push({id,kind:'content',version:1,data});}await ensureRounds();loaded=true;shell();
}else if(!location.hash.includes('type=recovery'))boot();
function cashLedger(category=''){const rows=list('income').filter(r=>!category||r.category===category).sort((a,b)=>b.date.localeCompare(a.date)),sum=a=>a.reduce((s,r)=>s+Number(r.amount),0);modal(category||'Business cash ledger',`<div class="metrics">${metric('This month',euro(sum(rows.filter(r=>r.date.startsWith(month())))))+metric('Previous month',euro(sum(rows.filter(r=>r.date.startsWith(shiftMonth(month(),-1))))))+metric('YTD',euro(sum(rows.filter(r=>r.date.startsWith(month().slice(0,4))&&r.date<=day()))))+metric('Total recorded',euro(sum(rows)))}</div><div class="section">${rows.map(r=>task(r.title||r.category,fmt(r.date)+' · '+euro(r.amount),r.category,'edit-income',`data-id="${r.id}"`)).join('')||empty('No receipts recorded.','Record actual cash received to build this ledger.')}</div><div class="form-actions">${btn('+ Record receipt','new-income','primary')}</div>`);}
function chartDetails(kind,key){if(kind==='facebook-month'){const rows=cashSummary(list('income'),key).rows.filter(r=>r.category==='Facebook monetization');modal(moLabel(key)+' · Facebook receipts',rows.map(r=>task(r.title,fmt(r.date)+' · '+euro(r.amount),r.category,'edit-income',`data-id="${r.id}"`)).join('')||'<p>No Facebook receipts recorded for this month.</p>');return}if(kind==='cash-month'){const d=cashSummary(list('income'),key);modal(moLabel(key)+' · received',ring(d.sources,euro(d.total),'CASH RECEIVED','cash')+d.rows.map(r=>task(r.title,fmt(r.date)+' · '+euro(r.amount),r.category,'edit-income',`data-id="${r.id}"`)).join(''));return}if(kind==='cash'){cashLedger(key);return}if(kind==='month'){const s=store.snapshots.find(r=>r.month===key);if(!s)return;modal(moLabel(key)+' · the full picture',`<p class="note">Snapshot captured ${fmt(s.captured_at)}. These are saved observations, not reconstructed historical member records.</p><div class="metrics">${metric('Active members',s.active_members)+metric('Gross MRR',euro(s.gross_mrr))+metric('Estimated net',euro(s.estimated_net))+metric('Net movement',euro(s.net_movement))}</div><div class="section">${[['New members',s.new_members],['Cancelled members',s.cancelled_members],['New MRR',euro(s.new_mrr)],['Lost MRR',euro(s.lost_mrr)],['Expansion',euro(s.expansion_mrr)],['Contraction',euro(s.contraction_mrr)],['Churn rate',s.churn_rate==null?'Not available':Number(s.churn_rate).toFixed(1)+'%'],...Object.entries(s.tiers||{})].map(([l,v])=>`<div class="movement-row"><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`);return}if(kind==='movement'){const rows=store.events.filter(e=>e.occurred_at.startsWith(month())&&e.category===key);modal(({new:'New member revenue',expansion:'Upgrade revenue',contraction:'Downgrade revenue',churn:'Cancelled revenue'})[key],rows.length?`<div class="task-list">${rows.map(e=>task(handle(member(e.member_id)),fmt(e.occurred_at)+' · '+euro(e.previous_mrr)+' → '+euro(e.current_mrr),euro(e.delta),'profile',`data-id="${e.member_id}"`)).join('')}</div>`:empty('No recorded changes.','This chart uses recorded membership changes only.'));return}const ms=actives().filter(m=>kind==='tier'?tier(m)===key:(m.country&&m.country!=='—'?m.country:'Unknown')===key),gross=mrr(ms);modal(esc(key)+' · beneath the numbers',`<div class="metrics">${metric('Members',ms.length)+metric('Gross MRR',euro(gross))+metric('Share of MRR',Math.round(gross/(mrr(store.members)||1)*100)+'%')+metric('Revenue / member',euro(ms.length?gross/ms.length:0))}</div><p class="note">${kind==='tier'&&key==='Basic (Legacy)'?'These members retain their grandfathered €3.50 price. ':''}Select a member to open their fulfilment, publishing history and membership details.</p>${memberRows(ms)}`,'profile');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-chart]');if(el)chartDetails(el.dataset.chart,el.dataset.key)});
document.addEventListener('keydown',e=>{const el=e.target.closest('[data-chart]');if(el&&el.tagName.toLowerCase()!=='button'&&['Enter',' '].includes(e.key)){e.preventDefault();chartDetails(el.dataset.chart,el.dataset.key)}});
function chartTooltip(el,x,y){let tip=$('chart-tooltip');if(!tip){tip=document.createElement('div');tip.id='chart-tooltip';tip.className='chart-tooltip';tip.setAttribute('role','tooltip');document.body.append(tip)}tip.textContent=el.dataset.tip+' · Click for details';tip.hidden=false;tip.style.left=Math.max(12,Math.min(innerWidth-290,x+14))+'px';tip.style.top=Math.max(12,Math.min(innerHeight-90,y+18))+'px';}
document.addEventListener('pointermove',e=>{const el=e.target.closest('[data-tip]');if(el)chartTooltip(el,e.clientX,e.clientY);else if($('chart-tooltip'))$('chart-tooltip').hidden=true});
document.addEventListener('focusin',e=>{const el=e.target.closest('[data-tip]');if(el){const r=el.getBoundingClientRect();chartTooltip(el,r.x,r.y)}else if($('chart-tooltip'))$('chart-tooltip').hidden=true});
